INSERT INTO referentiel_versions (version, nom_fr, nom_en, nom_mg, niveau, parent_version, actif) VALUES ('v3_0', 'GSAT Version 3.0', 'GSAT Version 3.0', NULL, 'OSN', NULL, true) ON CONFLICT (version) DO UPDATE SET nom_fr=EXCLUDED.nom_fr, nom_en=EXCLUDED.nom_en, niveau=EXCLUDED.niveau, actif=EXCLUDED.actif;
INSERT INTO dimensions (ref_id, code, nom_fr, nom_en, nom_mg, ordre) VALUES ((SELECT id FROM referentiel_versions WHERE version='v3_0'), 'D01', 'OSN–OMMS : Obligations institutionnelles', 'NSO–WOSM: Institutional Obligations', NULL, 1) ON CONFLICT (ref_id, code) DO UPDATE SET nom_fr=EXCLUDED.nom_fr, nom_en=EXCLUDED.nom_en, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '101', 'L''OSN est une entité légale ayant reçu une autorisation écrite valide d''une autorité compétente afin d''opérer dans le pays ou territoire où elle est officiellement établie.', 'The NSO is a legal entity that has received valid written authorization from a competent authority to operate in the country or territory where it is officially established.', NULL, '', '', NULL, true, true, true, 1, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '102', 'La Constitution de l''OSN inclut explicitement les éléments suivants : (a) Membre de l''OMMS et (b) Adhésion à la Constitution de l''OMMS.', 'The NSO''s Constitution explicitly includes the following elements: (a) Membership of WOSM and (b) Adherence to the WOSM Constitution.', NULL, '', '', NULL, true, true, true, 2, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '103', 'L''OSN a considéré la révision de sa Constitution par le conseil national et/ou l''assemblée générale au moins une fois au cours des cinq dernières années afin de s''assurer de sa conformité avec la Constitution de l''OMMS et les cadres légaux nationaux.', 'The NSO has considered reviewing its Constitution through the national council and/or general assembly at least once in the past five years to ensure compliance with the WOSM Constitution and national legal frameworks.', NULL, '', '', NULL, false, true, true, 3, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '104', 'L''OSN a remis son rapport annuel de l''année précédente à l''OMMS et reste conforme aux exigences de l''OMMS en matière de rapportage.', 'The NSO has submitted its annual report for the previous year to WOSM and remains compliant with WOSM reporting requirements.', NULL, '', '', NULL, true, true, true, 4, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '105', 'L''OSN a pris des mesures afin de garantir que les logos et marques scoutes soient légalement protégés dans le pays ou le territoire où elle est officiellement établie.', 'The NSO has taken steps to ensure that Scout logos and trademarks are legally protected in the country or territory where it is officially established.', NULL, '', '', NULL, false, true, true, 5, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '106', 'Tout usage commercial ou non commercial de la Marque du Scoutisme Mondial possède une licence valide délivrée par l''OMMS.', 'Any commercial or non-commercial use of the World Scouting Brand holds a valid licence issued by WOSM.', NULL, '', '', NULL, false, true, true, 6, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '107', 'L''OSN participe régulièrement aux Conférences Mondiales et Régionales du Scoutisme et veille à ce que sa délégation comprenne des jeunes de moins de 30 ans.', 'The NSO regularly participates in World and Regional Scout Conferences and ensures that its delegation includes young people under 30 years of age.', NULL, '', '', NULL, false, true, true, 7, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D01'), '108', 'L''OSN a défini et utilise un système de gestion de l''information qui permet d''identifier clairement tous types de documents officiels et d''assurer leur accessibilité à toutes les parties prenantes concernées.', 'The NSO has defined and uses an information management system that clearly identifies all types of official documents and ensures their accessibility to all relevant stakeholders.', NULL, '', '', NULL, false, true, true, 8, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO dimensions (ref_id, code, nom_fr, nom_en, nom_mg, ordre) VALUES ((SELECT id FROM referentiel_versions WHERE version='v3_0'), 'D02', 'Cadre de la gouvernance', 'Governance Framework', NULL, 2) ON CONFLICT (ref_id, code) DO UPDATE SET nom_fr=EXCLUDED.nom_fr, nom_en=EXCLUDED.nom_en, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D02'), '201', 'L''OSN dispose d''une assemblée générale (ou équivalent) qui est l''organe suprême de décision et qui se réunit conformément à la Constitution de l''OSN.', 'The NSO has a general assembly (or equivalent) that is the supreme decision-making body and meets in accordance with the NSO''s Constitution.', NULL, '', '', NULL, true, true, true, 1, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
