INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D02'), '203', 'L''OSN dispose d''un conseil national (ou organe équivalent) qui est responsable de la gouvernance stratégique entre les assemblées générales, et qui se réunit régulièrement.', 'The NSO has a national council (or equivalent body) responsible for strategic governance between general assemblies, which meets on a regular basis.', NULL, '', '', NULL, true, true, true, 3, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
