INSERT INTO dimensions (ref_id, code, nom_fr, nom_en, nom_mg, ordre) VALUES ((SELECT id FROM referentiel_versions WHERE version='v3_0'), 'D08', 'Programme des jeunes', 'Youth Programme', NULL, 8) ON CONFLICT (ref_id, code) DO UPDATE SET nom_fr=EXCLUDED.nom_fr, nom_en=EXCLUDED.nom_en, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D08'), '801', 'L''OSN dispose d''un programme des jeunes basé sur les éléments fondamentaux de la méthode scoute (système de patrouille, apprentissage par l''action, cadre symbolique, engagement par la Promesse et la Loi, progression personnelle, vie dans la nature, soutien adulte).', 'The NSO has a youth programme based on the fundamental elements of the Scout Method (patrol system, learning by doing, symbolic framework, commitment through Promise and Law, personal progression, nature activities, adult support).', NULL, '', '', NULL, true, true, true, 1, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
