INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D10'), '1006', 'L''OSN participe activement aux initiatives de partage de connaissances au niveau régional et mondial (ateliers, conférences, jumelages).', 'The NSO actively participates in knowledge-sharing initiatives at regional and global level (workshops, conferences, twinning).', NULL, '', '', NULL, false, true, true, 6, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D10'), '1007', 'L''OSN sollicite et utilise l''appui technique de l''OMMS et/ou du bureau régional pour renforcer ses capacités.', 'The NSO seeks and uses technical support from WOSM and/or the regional office to strengthen its capacities.', NULL, '', '', NULL, false, true, true, 7, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D10'), '1008', 'L''OSN intègre une culture d''amélioration continue dans sa gestion quotidienne (revues régulières, cycles PDCA ou équivalent).', 'The NSO embeds a culture of continuous improvement in its day-to-day management (regular reviews, PDCA cycles or equivalent).', NULL, '', '', NULL, false, true, true, 8, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
INSERT INTO criteres (dimension_id, code, libelle_fr, libelle_en, libelle_mg, guide_fr, guide_en, guide_mg, essentiel, socle, actif, ordre, source_codes, indicateur_erp) VALUES ((SELECT d.id FROM dimensions d JOIN referentiel_versions r ON d.ref_id=r.id WHERE r.version='v3_0' AND d.code='D10'), '1009', 'L''OSN évalue régulièrement l''efficacité de ses processus internes et les optimise en fonction des résultats.', 'The NSO regularly evaluates the effectiveness of its internal processes and optimises them based on results.', NULL, '', '', NULL, false, true, true, 9, '{}', '{}') ON CONFLICT (dimension_id, code) DO UPDATE SET libelle_fr=EXCLUDED.libelle_fr, libelle_en=EXCLUDED.libelle_en, guide_fr=EXCLUDED.guide_fr, guide_en=EXCLUDED.guide_en, essentiel=EXCLUDED.essentiel, actif=EXCLUDED.actif, ordre=EXCLUDED.ordre;
